      "headline": "VietCredit là “Đơn vị dẫn đầu về xu hướng sử dụng thẻ tín dụng nội địa trên thị trường”",
      "summary": "Tại Hội nghị Tổ chức Thành viên NAPAS 2026 ngày 13/11, VietCredit được vinh danh dẫn đầu xu hướng sử dụng thẻ tín dụng nội địa. Thành tích này phản ánh tốc độ mở rộng của thanh toán thẻ nội địa trên hạ tầng kết nối 68 tổ chức.",
